def transform(grid):
    """Fill each one-cell gap between matching non-background cells with 2."""
    out = [row[:] for row in grid]
    values = {value for row in grid for value in row}
    background = max(values, key=lambda value: sum(row.count(value) for row in grid))
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] == row[c + 1] != background:
                out[r][c] = 2
    return out

if __name__ == "__main__":
    sample = [[3, 8, 3, 8, 3]]
    assert transform(sample) == [[3, 8, 2, 8, 3]]
